// Fish Proxy — Service Worker (embedded build)
// Engine files are embedded as data: URLs at build time — this file has
// zero external dependencies once built. Host it next to index.html on
// any static host and Fish Proxy works with no other files needed.

// data: URLs work fine with importScripts — the restriction only applies
// to the initial navigator.serviceWorker.register() call, not to scripts
// a SW loads internally afterward.
importScripts('data:application/javascript;base64,')

const { ScramjetServiceWorker } = $scramjetLoadWorker()
const scramjet = new ScramjetServiceWorker()

self.addEventListener('install', () => {
  self.skipWaiting()
})

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim())
})

async function handleRequest(event) {
  await scramjet.loadConfig()
  if (!scramjet.route(event)) return fetch(event.request)
  return scramjet.fetch(event)
}

self.addEventListener('fetch', (event) => {
  if (new URL(event.request.url).origin !== self.location.origin) return
  event.respondWith(handleRequest(event))
})
